#include "teya/editor/EditorContext.h"
namespace teya::editor { SimulationMode EditorContext::simulationMode()const{return mode_;} void EditorContext::stop(){mode_=SimulationMode::Stopped;} void EditorContext::play(){mode_=SimulationMode::Playing;} void EditorContext::pause(){mode_=SimulationMode::Paused;} void EditorContext::step(){if(mode_!=SimulationMode::Playing&&mode_!=SimulationMode::Stopped)mode_=SimulationMode::StepRequested;} bool EditorContext::consumeSimulationStep(){if(mode_==SimulationMode::Playing)return true;if(mode_==SimulationMode::StepRequested){mode_=SimulationMode::Paused;return true;}return false;} bool EditorContext::allowsGameInput(const InputGateState&s){const bool active=s.simulation==SimulationMode::Playing||s.simulation==SimulationMode::StepRequested;const bool gameOwnsInput=s.gameViewFocused||s.captureEnabled;const bool keyboardBlocked=s.keyboardRequired&&s.wantKeyboard&&!gameOwnsInput;const bool mouseBlocked=s.mouseRequired&&s.wantMouse&&!gameOwnsInput;return active&&gameOwnsInput&&!s.modalOpen&&!keyboardBlocked&&!mouseBlocked;} }
